1: // guard-file-size — per-role split triggers (AGENTS.md stack rule; kit
2: // FACTORY DoD). Production modules (js/**, css/**) fail over 300 lines so
3: // logic splits into focused ES modules/stylesheets; additive test suites
4: // (test/**, e2e/**) fail over 450 lines; static pages (*.html, no partials/
5: // bundler) fail over 550 lines. Non-vacuity: if the selection is empty the
6: // guard itself is broken, so that fails too.
7: import { readFileSync, readdirSync, statSync } from 'node:fs';
8: import { join, relative, sep, extname } from 'node:path';
9: 
10: const LIMITS = {
11:   html: 550,
12:   test: 450,
13:   code: 300,
14: };
15: 
16: function limitFor(file) {
17:   if (extname(file) === '.html') return LIMITS.html;
18:   if (file.startsWith('test/') || file.startsWith('e2e/')) return LIMITS.test;
19:   return LIMITS.code;
20: }
21: const SKIP_DIRS = new Set([
22:   '.git',
23:   'node_modules',
24:   'coverage',
25:   'test-results',
26:   'playwright-report',
27:   '.cache',
28: ]);
29: const SOURCE_DIRS = ['js', 'css', 'e2e', 'test'];
30: const SOURCE_EXT = new Set(['.js', '.css', '.html']);
31: 
32: function walk(dir, out = []) {
33:   for (const name of readdirSync(dir)) {
34:     if (SKIP_DIRS.has(name)) continue;
35:     const full = join(dir, name);
36:     if (statSync(full).isDirectory()) walk(full, out);
37:     else out.push(relative('.', full).split(sep).join('/'));
38:   }
39:   return out;
40: }
41: 
42: const candidates = [
43:   ...SOURCE_DIRS.filter((d) => {
44:     try {
45:       return statSync(d).isDirectory();
46:     } catch {
47:       return false;
48:     }
49:   }).flatMap((d) => walk(d)),
50:   ...walk('.').filter((f) => !f.includes('/') && SOURCE_EXT.has(extname(f))),
51: ];
52: 
53: if (candidates.length === 0) {
54:   console.error('guard-file-size: selection is empty — the guard itself is broken (non-vacuity).');
55:   process.exit(1);
56: }
57: 
58: const offenders = [];
59: for (const file of candidates) {
60:   if (!SOURCE_EXT.has(extname(file))) continue;
61:   const limit = limitFor(file);
62:   const lines = readFileSync(file, 'utf8').split('\n');
63:   if (lines.at(-1) === '') lines.pop();
64:   if (lines.length > limit) offenders.push({ file, lines: lines.length, limit });
65: }
66: 
67: if (offenders.length > 0) {
68:   for (const { file, lines, limit } of offenders) {
69:     console.error(
70:       `guard-file-size: ${file} is ${lines} lines (> ${limit}) — split by responsibility.`,
71:     );
72:   }
73:   process.exit(1);
74: }
75: console.log(
