// DOCUMENTS: the Stage 6 component — an authoritative DNS resolver with a
// tick-TTL cache ledger, mirroring the Cache's tick-based TTL pattern
// (js/sim/cache.js): a real Map lookup on the request path rather than a
// probability. The authoritative table lives in-component
// (`example.com -> 10.1` in 6a; Stage 6b adds a CDN name); `lookup` consults
// it only on a cache miss or an expired entry, and an entry answered inside
// ttlTicks is an incrementing cachedHits with no authoritative consult.
// Deterministic by construction: no clock, no RNG — time arrives as the
// `currentTick` argument.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration). An unknown name answers `{ status: 'NX' }` —
// never a throw at the DNS layer (the browser renders the NX card; the
// throw rule applies to cross-subnet addresses, not to names).
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const authoritative = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry:
  // cached at tick T with ttlTicks = 300 means alive through tick T + 299.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) cache.delete(entry.name);
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      // CHECKS: a hit inside ttlTicks increments cachedHits and never
      // consults the authoritative table; an expired entry is already
      // evicted above, so it can never be answered from the ledger.
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'HIT', target: entry.target };
    }
    const target = authoritative.get(name);
    if (target === undefined) {
      lastLookup = { name, status: 'NX', target: null, atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'MISS', target, atTick: currentTick };
    return { status: 'MISS', target };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative: Object.fromEntries(authoritative),
      lastLookup,
      cache: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet router joining the 10.x
// and 20.x network instances at two interfaces (left 10.65, right 20.1). Any
// frame whose from/to subnets differ takes exactly one router hop
// (`routed` counter, the trace shows the hop); same-subnet sends are the
// network's own job and never touch the router. Nothing lives in subnet 20
// in 6a besides the router's own presence: 20.1 (the router's 20-side) is
// the only reachable target — the engine registers the router there — while
// sends to an unregistered 20.x host (20.9) fail loud at the destination
// network's resolve, mirroring network.js's fail-loud contract.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP, a pair whose two interfaces share a subnet, and a route before
// join(leftNetwork, rightNetwork) — fail-loud over silent mis-wiring.
const MINI_IP = /^\d+\.\d+$/;

const subnetOf = (addr) => String(addr).split('.')[0];

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  if (subnetOf(leftAddress) === subnetOf(rightAddress)) {
    throw new Error(
      `router: interfaces ${leftAddress} / ${rightAddress} must sit in different subnets`,
    );
  }
  let left = null;
  let right = null;
  let routed = 0;
  let lastRoute = null;

  // The router joins two network instances once, at engine construction.
  function join(leftNetwork, rightNetwork) {
    if (!leftNetwork || !rightNetwork) {
      throw new Error('router: join needs both network instances');
    }
    left = leftNetwork;
    right = rightNetwork;
  }

  function networkFor(to) {
    if (!left || !right) throw new Error('router: no networks joined');
    const toSubnet = subnetOf(to);
    if (toSubnet === subnetOf(rightAddress)) return right;
    if (toSubnet === subnetOf(leftAddress)) return left;
    throw new Error(`router: no route to ${to}`);
  }

  // One router hop: the frame crosses subnets exactly once, then the
  // destination subnet's own network delivers it (its resolve fails loud on
  // an unregistered host). `isYou` rides through untouched, like the
  // network's own deliverToQueue contract.
  function route({ from, to, request, isYou = false, id = null, atTick = null }) {
    if (!MINI_IP.test(from)) {
      throw new Error(`router: invalid mini-IP address ${from}`);
    }
    if (!MINI_IP.test(to)) {
      throw new Error(`router: invalid mini-IP address ${to}`);
    }
    const remote = networkFor(to);
    routed += 1;
    lastRoute = { from, to, request, atTick };
    if (id !== null) {
      remote.resolve(to).enqueue({ id, from, to, request, atTick, isYou });
      return { from, to, request, routed: true };
    }
    const response = remote.resolve(to).handleRequest(request);
    return { from, to, request, response };
  }

  // The router's own 20-side presence answers its interface at 20.1 —
  // the only reachable target in subnet 20 until Stage 6b's CDN edge.
  function handleRequest() {
    return `200 Router interface ${rightAddress}`;
  }

  function snapshot() {
    return { leftAddress, rightAddress, routed, lastRoute };
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },
    join,
    route,
    handleRequest,
    snapshot,
  };
}

