parseResponse(raw) {
  const [statusToken, ...bodyParts] = String(raw).trim().split(' ');
  // CHECKS: a non-numeric status token (the DNS layer's NX answer —
  // no GET was emitted, so there is no HTTP status) rides through as
  // the verbatim token instead of collapsing to NaN.
  const status = Number(statusToken);
  return {
    status: Number.isNaN(status) ? statusToken : status,
    body: bodyParts.join(' '),
  };
},

