export const TICK_MS = 100;
const QUEUE_BAR_SATURATION = 20; // bar reads full at 20 queued requests
// Total hops per stage's trace shape (trace.js and engine.traceHop agree).
// Stage 6: 10 with a hosted path (2 DNS hops ride before the LB route),
// 8 unchanged host-less — the per-trace count rides trace.totalHops.
const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 10 };

const HOP_START_SENTENCE = 'Idle — type a path and click Go or Step 1 Hop ->';

function fillPercent(depth) {
  return `${Math.min(100, Math.round((depth / QUEUE_BAR_SATURATION) * 100))}%`;
}

// The Stage 5 chain a request actually took, hops 2..8 in stage-5
// numbering: route to LB, LB queue pick, the cache/db/async story, the
// response emit, the network delivery, the browser render, and the worker
// tail. Stage 6 reuses these sentences verbatim (+2 hop numbers for a
// hosted path, byte-identical host-less) so the narrative consumes the
// same actual trace messages (DL-1/DL-3).
function chainSentences(startHop, denom, t, snapshot, from, serverAddress) {
  const target = t.targetServer ?? '10.11';
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  const hop = (n, text) => `Hop ${n}/${denom}: ${text}`;
  let story;
  let serve;
  let tail;
  if (t.asyncJob) {
    story = `WebServer (${target}) enqueues job to WorkerQueue (10.40)`;
    serve = `WebServer (${target}) -> "202 Accepted"`;
    tail = `Worker (${worker}) processed job and committed to Database (10.30)`;
  } else {
    const db = snapshot.database ?? {};
    const primary = db.primaryAddress ?? '10.30';
    const replica = db.replicaAddress ?? '10.31';
    const lag = db.replicationLagTicks ?? 3;
    story =
      t.dbOp === 'WRITE'
        ? `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
        : t.dbOp === 'SELECT' && t.dbStale
          ? `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
          : t.dbOp === 'SELECT'
            ? `Database SELECT @ Replica (${replica}) — fresh`
            : `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
    serve = `WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`;
    tail = `Worker (${worker}) idle — no async jobs in this trace`;
  }
  return [
    hop(startHop, `Network (10.x) routes to LoadBalancer (${serverAddress})`),
    hop(startHop + 1, `LoadBalancer (${serverAddress}) -> ${target} queue`),
    hop(startHop + 2, story),
    hop(startHop + 3, serve),
    hop(startHop + 4, `Network delivers ${t.status} response to ${from}`),
    hop(startHop + 5, `Browser (${from}) received and displayed ${t.status}`),
    hop(startHop + 6, tail),
  ];
}

// One hop-status sentence per hop, in hop order, for each stage's trace
// shape: 4 hops in Stage 1 (emit, route, serve, render), 5 in Stage 2 (LB
// round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
// Stage 4 (the database hop after the cache check), 8 in Stage 5, and
// Stage 6 branching on the host grammar: hosted adds exactly 2 DNS hops
// (10 total), host-less keeps the Stage 5 story byte-identical, and an
// unknown name answers NX — DNS ask + NX answer, the browser renders the
// NX card, no GET is ever emitted.
function hopSentences(stage, snapshot, from, serverAddress) {
  const t = snapshot.trace ?? {};
  const target = t.targetServer ?? '10.11';
  if (stage === 6) {
    const dnsAddr = snapshot.dns?.address ?? '10.60';
    if (t.nx) {
      return [
        `Hop 1/3: Browser (${from}) emits "${t.request}"`,
        `Hop 2/3: Browser (${from}) asks DNS (${dnsAddr}) to resolve ${t.host}`,
        `Hop 3/3: DNS (${dnsAddr}) answers NX — no record for ${t.host}, the browser renders the NX card (no GET emitted)`,
      ];
    }
    if (t.hosted) {
      return [
        `Hop 1/10: Browser (${from}) emits "${t.request}"`,
        `Hop 2/10: Browser (${from}) asks DNS (${dnsAddr}) to resolve ${t.host}`,
        `Hop 3/10: DNS (${dnsAddr}) answers ${t.dnsTarget} (${t.dnsStatus})`,
        ...chainSentences(4, 10, t, snapshot, from, serverAddress),
      ];
    }
    // Host-less: the Stage 5 story byte-identical — no DNS hop anywhere.
    return [
      `Hop 1/8: Browser (${from}) emits "${t.request}"`,
      ...chainSentences(2, 8, t, snapshot, from, serverAddress),
    ];
  }
  if (stage === 5) {
    return [
      `Hop 1/8: Browser (${from}) emits "${t.request}"`,
      ...chainSentences(2, 8, t, snapshot, from, serverAddress),
    ];
  }

