function stepOneHop() {
  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  // A live trace carries its own hop total (Stage 6 branches on the host
  // grammar: 10 hosted, 8 host-less, 3 NX); the stage constant is only
  // the fallback.
  const totalHops = traceTotal(snapshot);
  // PINS: hop 1 emission starts a new trace run — that run (whole, hops
  // ascending) floats above the previous run in #journey-log.
  if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: snapshot.trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

$('btn-next-hop').addEventListener('click', stepOneHop);

$('btn-play-request').addEventListener('click', () => {
  if (timer) pause();
  // The trace's own total rules the run (an NX trace ends at hop 3, not
  // the stage's hosted maximum), and a hop-1 reset after the first click
  // means the previous trace already wrapped — stop instead of looping.
  let started = false;
  const iv = setInterval(() => {
    const snapshot = stepOneHop();
    const total = traceTotal(snapshot);
    if (snapshot.trace.hop === total || (started && snapshot.trace.hop === 1)) {
      clearInterval(iv);
    }
    started = true;
  }, TICK_MS);
});

$('btn-url-go').addEventListener('click', () => {
  if (timer) pause();
  for (let i = 0; i < totalHopsFor(currentStage) + 1; i += 1) {
    const snapshot = stepOneHop();
    if (snapshot.trace.hop === traceTotal(snapshot)) break;
  }
});

