// DOCUMENTS: the Stage 2-6 request chain — every hop after the browser's
// emit that the network/LB/queue/cache machinery answers (it does not fake
// a shortcut). Stage 2 adds the LB's round-robin pick; Stage 3 splits the
// backend serve into the cache-aside lookup and the response emission;
// Stage 4 inserts the Database hop (the WRITE to Primary 10.30, the fresh
// or stale SELECT from Replica 10.31, or the SKIP a warm cache HIT earns);
// Stage 5 adds the async queue tail. Stage 6 rides the exact same chain —
// in place for a host-less path (byte-identical story) and shifted by its
// 2 DNS hops for a hosted one.
//
// `state` is the { trace, served } box the caller owns; the chain mutates
// the trace's hop/request fields and holds the drained response record
// between the cache check and the response emit.
//
// CHECKS: chain positions are keyed in Stage 5 chain space (q), so a
// hosted Stage 6 trace advances the same positions at trace hop q + 3 —
// the frames and hop texts stay identical to the chain the crowd uses.
export function chainStep(state, ctx) {
  const { trace } = state;
  const {
    stage,
    serverAddress,
    servers,
    lb = null,
    cache = null,
    database = null,
    workerQueue = null,
    bumpTick,
    getTick,
    onServe,
    onFinish,
  } = ctx;
  const hosted6 = stage === 6 && trace.hosted;
  const q = hosted6 ? trace.hop - 3 : trace.hop; // position in chain space
  const next = (n) => (state.trace.hop = n + (hosted6 ? 3 : 1));
  let frame = null;

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: trace.request,
      response: trace.response,
    });
  }

  // Stages 3-4: the visible cache-lookup hop — the target backend checks
  // Cache and serves the queued request; the response record is held one
  // hop so the learner watches the lookup before the response leaves.
  function cacheHop(qNext) {
    next(qNext);
    const backend = backendFor(trace.targetServer);
    state.served = drainUntilYou(backend);
    const served = state.served;
    if (served) {
      trace.cacheStatus = served.cacheStatus ?? null;
      trace.dbOp = served.dbOp ?? null;
      trace.dbStale = Boolean(served.dbStale);
      trace.asyncJob = Boolean(served.asyncJob);
      return `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
    }
    return null;
  }

  // The backend narrative a drained request actually took: an async POST
  // enqueues to the WorkerQueue, a WRITE lands on the primary, a SELECT
  // reads the replica fresh or stale, and a warm cache HIT skips the
  // database entirely (no phantom stories — DL-4).
  function storyFrame(backend) {
    const served = state.served;
    if (served.asyncJob) {
      return `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.path})`;
    }
    if (trace.dbOp === 'WRITE') {
      return `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
    }
    if (trace.dbOp === 'SELECT') {
      return `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
    }
    return `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
  }

  // Stage 5+: the merged cache/db/async hop.
  function storyHop(qNext) {
    next(qNext);
    const backend = backendFor(trace.targetServer);
    state.served = drainUntilYou(backend);
    const served = state.served;
    if (served) {
      trace.cacheStatus = served.cacheStatus ?? null;
      trace.dbOp = served.dbOp ?? null;
      trace.dbStale = Boolean(served.dbStale);
      trace.asyncJob = Boolean(served.asyncJob);
      return storyFrame(backend);
    }
    return null;
  }

  // The response-emit hop; Stage 3's frame omits the `cache` word.
  function serveHop(qNext, cacheWord) {
    next(qNext);
    const served = state.served;
    if (served) {
      serve(served);
      return served.asyncJob
        ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
        : `${trace.targetServer} -> ${trace.from} | ${served.response} ${cacheWord}`;
    }
    return null;
  }

  if (q === 1) {
    next(2);
    frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) to LoadBalancer`;
  } else if (q === 2) {
    next(3);
    const atTick = bumpTick();
    const target = lb.enqueue({
      id: `you:${atTick}`,
      from: trace.from,
      to: serverAddress,
      request: trace.request,
      atTick,
      isYou: true,
    });
    trace.targetServer = target;
    frame = `LB ${serverAddress} -> ${target} (${trace.request}) queued`;
  } else if (stage === 2 && q === 3) {
    next(4);
    const backend = backendFor(trace.targetServer);
    const you = drainUntilYou(backend);
    if (you) {
      serve(you);
      frame = `${backend.address} -> ${trace.from} | ${you.response}`;
    }
  } else if (stage === 2 && q === 4) {
    next(5);
    finish(trace.targetServer ?? serverAddress);
  } else if (stage === 3 && q === 3) {
    frame = cacheHop(4);
  } else if (stage === 3 && q === 4) {
    frame = serveHop(5, `(${trace.cacheStatus})`);
  } else if (stage === 3 && q === 5) {
    next(6);
    finish(trace.targetServer ?? serverAddress);
  } else if (stage === 4 && q === 3) {
    frame = cacheHop(4);
  } else if (stage === 4 && q === 4) {
    // The database hop — the WRITE landed on Primary 10.30 (replication
    // queued toward 10.31), the SELECT read Replica 10.31 fresh or stale,
    // and a warm cache HIT skips the database entirely.
    next(5);
    if (state.served) frame = storyFrame(backendFor(trace.targetServer));
  } else if (stage === 4 && q === 5) {
    frame = serveHop(6, `(cache ${trace.cacheStatus})`);
  } else if (stage === 4 && q === 6) {
    next(7);
    finish(trace.targetServer ?? serverAddress);
  } else if ((stage === 5 || stage === 6) && q === 3) {
    frame = storyHop(4);
  } else if ((stage === 5 || stage === 6) && q === 4) {
    frame = serveHop(5, `(cache ${trace.cacheStatus})`);
  } else if ((stage === 5 || stage === 6) && q === 5) {
    next(6);
    frame = `Network delivered ${trace.status} response to ${trace.from}`;
  } else if ((stage === 5 || stage === 6) && q === 6) {
    next(7);
    finish(trace.targetServer ?? serverAddress);
    frame = `Browser ${trace.from} received and displayed ${trace.status}`;
  } else if ((stage === 5 || stage === 6) && q === 7) {
    // The worker tail: an async job finishes and commits; a request that
    // was served synchronously finds the worker idle.
    next(8);
    const dbTarget = database ? database.primaryAddress : '10.30';
    const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
    frame = trace.asyncJob
      ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
      : `Worker ${workerAddr} idle — no async jobs in this trace`;
  }
  return frame;
}

// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); stages 2-6
// then ride the shared chain machine (trace-chain.js).
//
// Stage 6 grammar: the trace branches on whether the browser path carries
// a host (`<host>/<path>`, split on the first '/') or is host-less
// (`/<path>`). A hosted path rides 2 DNS hops before the chain (10 hops
// total): the real `dns.lookup` answers ask then answer, and the GET is
// only emitted with the resolved target. A host-less path keeps the
// Stage 5 8-hop story byte-identical — no DNS hop. An unknown name answers
// NX: DNS ask + `NX no record` only, the browser renders the NX card, and
// NO GET is ever emitted (3 hops).
//
// The machine owns the trace state and hop transitions; the engine owns
// the clock, the served-exchange record, and browser delivery, handed in
// as the four callbacks below.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance.
import { chainStep } from './trace-chain.js';

export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
    throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  if (stage >= 6 && !dns) {
    throw new Error('trace: stage 6 needs the DNS resolver attached');
  }
  const state = { trace: freshTrace(), served: null };
  const ctx = {
    stage,
    serverAddress,
    servers,
    lb,
    cache,
    database,
    workerQueue,
    bumpTick,
    getTick,
    onServe,
    onFinish,
  };

  function freshTrace() {
    return {
      hop: 0,
      method: 'GET',
      path: '/about',
      from: '10.2',
      request: 'GET /about',
      targetServer: null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      asyncJob: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
      hosted: false,
      host: null,
      pathOnly: null,
      dnsStatus: null,
      dnsTarget: null,
      nx: false,
      totalHops: 0,
    };
  }

  function stageHops() {
    return stage === 5 || stage === 6 ? 8 : stage === 4 ? 7 : stage === 3 ? 6 : stage === 2 ? 5 : 4;
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const trace = state.trace;
      const totalHops = trace.totalHops || stageHops();
      if (trace.hop === 0 || trace.hop >= totalHops) {
        const request = `${method} ${path}`;
        // Stage 6 host grammar: `example.com/about` splits on the first
        // '/'; a bare path never touches DNS (named counter-example: a
        // stage-6 `GET /about` keeps the stage-5 story byte-identical).
        let hosted = false;
        let host = null;
        let pathOnly = path;
        if (stage >= 6) {
          const slashAt = String(path).indexOf('/');
          if (slashAt > 0) {
            hosted = true;
            host = path.slice(0, slashAt);
            pathOnly = path.slice(slashAt);
          }
        }
        state.trace = {
          ...freshTrace(),
          hop: 1,
          method,
          path,
          from,
          request,
          targetServer: stage === 1 ? serverAddress : null,
          hosted,
          host,
          pathOnly,
          totalHops: stage >= 6 ? (hosted ? stageHops() + 2 : stageHops()) : stageHops(),
        };
        state.served = null;
        return `${from} -> ${serverAddress} | ${request}`;
      }
      if (stage === 1) return stage1Hop(trace);
      if (stage >= 6 && trace.hosted && !trace.nx && trace.hop <= 3) return dnsHop(trace);
      return chainStep(state, ctx);
    },

    snapshot() {
      return { ...state.trace };
    },
  };

  // Stage 1 keeps its own 4-hop shape: emit, route into the FIFO queue,
  // serve, render.
  function stage1Hop(trace) {
    if (trace.hop === 1) {
      trace.hop = 2;
      const atTick = bumpTick();
      network.deliverToQueue({
        id: `you:${atTick}`,
        from: trace.from,
        to: serverAddress,
        request: trace.request,
        atTick,
        isYou: true,
      });
      return `routed ${trace.from} -> ${serverAddress} (${trace.request}) into queue`;
    }
    if (trace.hop === 2) {
      trace.hop = 3;
      for (;;) {
        const batch = servers[0].step(getTick());
        const you = batch.find((item) => item.isYou);
        if (you) {
          trace.response = you.response;
          trace.status = you.status;
          trace.body = you.body;
          trace.routeId = you.routeId;
          onServe(you);
          return `${serverAddress} -> ${trace.from} | ${you.response}`;
        }
        if (batch.length === 0) return null;
      }
    }
    trace.hop = 4;
    onFinish({
      from: trace.from ?? '10.2',
      to: serverAddress,
      request: trace.request,
      response: trace.response,
    });
    return null;
  }

  // Stage 6 DNS hops: the ask runs the real resolver lookup — the tick-TTL
  // cache ledger answers a warm name, the authoritative table a cold one,
  // an unknown name is NX. The answer re-arms the GET with the resolved
  // target and hands the trace to the chain (+2); NX answers, the browser
  // renders the NX card, and NO GET is ever emitted.
  function dnsHop(trace) {
    if (trace.hop === 2) {
      trace.hop = 3;
      const result = dns.lookup(trace.host, getTick());
      trace.dnsStatus = result.status;
      trace.dnsTarget = result.target ?? null;
      return `${trace.from} -> ${dns.address} | resolve ${trace.host}`;
    }
    if (trace.dnsStatus === 'NX') {
      trace.nx = true;
      trace.totalHops = 3;
      trace.response = 'NX no record';
      trace.status = 'NX';
      trace.body = 'no record';
      onFinish({
        from: trace.from,
        to: dns.address,
        request: trace.request,
        response: 'NX no record',
      });
      return `${dns.address} -> ${trace.from} | NX no record (no GET emitted)`;
    }
    trace.hop = 4;
    trace.request = `GET ${trace.pathOnly}`;
    trace.path = trace.pathOnly;
    return `${dns.address} -> ${trace.from} | ${trace.dnsTarget} (${trace.dnsStatus})`;
  }
}

export const DEFAULT_RING_GAP = 400;

const STAGE_RINGS = {
  1: [
    ['ring-compute', 'RING 1 · WEBSERVER'],
    ['ring-network', 'RING 2 · NETWORK'],
    ['ring-clients', 'RING 3 · BROWSERS'],
  ],
  2: [
    ['ring-compute', 'RING 1 · WEBSERVERS'],
    ['ring-lb', 'RING 2 · LOADBALANCER'],
    ['ring-network', 'RING 3 · NETWORK'],
    ['ring-clients', 'RING 4 · BROWSERS'],
  ],
  3: [
    ['ring-cache', 'RING 1 · CACHE'],
    ['ring-compute', 'RING 2 · WEBSERVERS'],
    ['ring-lb', 'RING 3 · LOADBALANCER'],
    ['ring-network', 'RING 4 · NETWORK'],
    ['ring-clients', 'RING 5 · BROWSERS'],
  ],
  4: [
    ['ring-db', 'RING 1 · DATABASE'],
    ['ring-cache', 'RING 2 · CACHE'],
    ['ring-compute', 'RING 3 · WEBSERVERS'],
    ['ring-lb', 'RING 4 · LOADBALANCER'],
    ['ring-network', 'RING 5 · NETWORK'],
    ['ring-clients', 'RING 6 · BROWSERS'],
  ],
  5: [
    ['ring-db', 'RING 1 · DATABASE'],
    ['ring-workers', 'RING 2 · WORKERS'],
    ['ring-cache', 'RING 3 · CACHE'],
    ['ring-compute', 'RING 4 · WEBSERVERS'],
    ['ring-lb', 'RING 5 · LOADBALANCER'],
    ['ring-network', 'RING 6 · NETWORK'],
    ['ring-clients', 'RING 7 · BROWSERS'],
  ],
  6: [
    ['ring-db', 'RING 1 · DATABASE'],
    ['ring-workers', 'RING 2 · WORKERS'],
    ['ring-cache', 'RING 3 · CACHE'],
    ['ring-compute', 'RING 4 · WEBSERVERS'],
    ['ring-lb', 'RING 5 · LOADBALANCER'],
    ['ring-network', 'RING 6 · NETWORK'],
    ['ring-dns', 'RING 7 · DNS'],
    ['ring-clients', 'RING 8 · BROWSERS'],
  ],
};

export const ORRERY_RINGS = buildOrreryRings(DEFAULT_RING_GAP, 1);

export function buildOrreryRings(ringGap = DEFAULT_RING_GAP, stage = 1) {
  if (!Number.isFinite(ringGap) || ringGap <= 0) {
    throw new Error('layout: ringGap must be a finite number > 0');
  }
  const ringSpecs = STAGE_RINGS[stage];
  if (!ringSpecs) {
    throw new Error(`layout: unknown stage ${stage} (expected 1-6)`);
  }
  const gap = Math.round(ringGap);
  return ringSpecs.map(([id, label], k) => ({ id, radius: (k + 1) * gap, label }));
}

export function polarToWorld(radius, angleDeg) {
  const rad = (angleDeg * Math.PI) / 180;
  return { x: Math.round(radius * Math.cos(rad)), y: Math.round(radius * Math.sin(rad)) };
}

function computeSatellites(users, outerRadius) {
  const count = Math.max(0, Math.round(users));
  const leftCount = Math.ceil(count / 2);
  const rightCount = count - leftCount;
  const satellites = [];
  const place = (arcCount, startAngle) => {
    for (let j = 0; j < arcCount; j += 1) {
      const angleDeg = startAngle + ((j + 1) / (arcCount + 1)) * 37;
      const { x, y } = polarToWorld(outerRadius, angleDeg);
      satellites.push({ index: satellites.length, x, y, angleDeg });
    }
  };
  place(leftCount, 135);
  place(rightCount, 188);
  return satellites;
}

function makeWire(id, fromId, toId, from, to) {
  return {
    id,
    fromId,
    toId,
    x1: from.x,
    y1: from.y,
    x2: to.x,
    y2: to.y,
    midX: Math.round((from.x + to.x) / 2),
    midY: Math.round((from.y + to.y) / 2),
  };
}

// CHECKS: computeStageLayout validates the stage range rather than silently
// rendering an unknown topology as empty space.
export function computeStageLayout(
  stage = 1,
  users = 5,
  { ringGap = DEFAULT_RING_GAP, activeBrowser = '10.2' } = {},
) {
  if (stage < 1 || stage > 6) {
    throw new Error(`layout: unknown stage ${stage} (expected 1-6)`);
  }
  const rings = buildOrreryRings(ringGap, stage);
  const gap = Math.round(ringGap);
  const ringRadius = (id) => rings.find((ring) => ring.id === id).radius;
  const pos = (id, ring, radius, angleDeg) => ({
    id,
    ring,
    radius,
    angleDeg,
    ...polarToWorld(radius, angleDeg),
  });

  // Addressable browsers on the outer client ring (Ring 3 in Stage 1, Ring 4
  // in Stage 2, Ring 5 in Stage 3): slot 0 (mini-IP 10.2) sits at 180° — the
  // expanded #node-browser spot — and slots 1 .. users - 1 (10.3 ..
  // 10.(users + 1)) take the satellite arc positions. Compact nodes render
  // at every slot not currently expanded.
  const browserCount = Math.max(0, Math.round(users));
  const outerRadius = rings[rings.length - 1].radius;
  const walkArcs = computeSatellites(Math.max(0, browserCount - 1), outerRadius);
  const browserSlots = Array.from({ length: browserCount }, (_, i) => {
    if (i === 0)
      return { index: 0, address: '10.2', angleDeg: 180, ...polarToWorld(outerRadius, 180) };
    return { index: i, address: `10.${i + 2}`, ...walkArcs[i - 1] };
  });
  const activeSlot = browserSlots.find((slot) => slot.address === String(activeBrowser)) ?? {
    index: 0,
    address: '10.2',
    angleDeg: 180,
    ...polarToWorld(outerRadius, 180),
  };

  const nodes = {
    'node-browser': {
      id: 'node-browser',
      ring: rings[rings.length - 1].id,
      radius: outerRadius,
      angleDeg: activeSlot.angleDeg,
      x: activeSlot.x,
      y: activeSlot.y,
      address: activeSlot.address,
    },
  };
  const networkRing = rings.find((ring) => ring.id === 'ring-network');
  nodes['node-network'] = pos('node-network', 'ring-network', networkRing.radius, 180);
  // Wires are declared after the nodes exist; this helper keeps every wire
  // a one-line declaration between already-positioned cards.
  const wires = [];
  const wire = (id, fromId, toId) =>
    wires.push(makeWire(id, fromId, toId, nodes[fromId], nodes[toId]));
  wire('wire-browser-network', 'node-browser', 'node-network');
  const computeRing = rings.find((ring) => ring.id === 'ring-compute');
  if (stage === 1) {
    nodes['node-webserver'] = pos('node-webserver', 'ring-compute', computeRing.radius, 180);
    wire('wire-network-webserver', 'node-network', 'node-webserver');
  } else {
    nodes['node-lb'] = pos('node-lb', 'ring-lb', ringRadius('ring-lb'), 180);
    // Both backends sit squarely on the Compute ring: Stage 2 uses 210°/150°
    // (bottom-left / top-left arc); Stages 3–4 open the arc to 200°/160° so
    // the cache wires down the ring stack stay clear of the LB wire.
    const backendAngle1 = stage >= 3 ? 200 : 210;
    const backendAngle2 = stage >= 3 ? 160 : 150;
    nodes['node-webserver'] = pos('node-webserver', 'ring-compute', computeRing.radius, backendAngle1);
    nodes['node-webserver-2'] = pos(
      'node-webserver-2',
      'ring-compute',
      computeRing.radius,
      backendAngle2,
    );
    wire('wire-network-lb', 'node-network', 'node-lb');
    wire('wire-lb-webserver', 'node-lb', 'node-webserver');
    wire('wire-lb-webserver-2', 'node-lb', 'node-webserver-2');
    if (stage >= 3) {
      // Cache-aside: the shared Cache sits behind both backends, each with
      // its own lookup wire down the ring stack (Ring 1 in Stage 3, Ring 2
      // in Stage 4).
      nodes['node-cache'] = pos('node-cache', 'ring-cache', ringRadius('ring-cache'), 180);
      wire('wire-webserver-cache', 'node-webserver', 'node-cache');
      wire('wire-webserver-2-cache', 'node-webserver-2', 'node-cache');
    }
    if (stage >= 4) {
      nodes['node-db'] = pos('node-db', 'ring-db', ringRadius('ring-db'), 180);
      wire('wire-cache-db', 'node-cache', 'node-db');
    }
    if (stage >= 5) {
      nodes['node-queue'] = pos('node-queue', 'ring-workers', ringRadius('ring-workers'), 200);
      nodes['node-worker'] = pos('node-worker', 'ring-workers', ringRadius('ring-workers'), 160);
      wire('wire-cache-queue', 'node-cache', 'node-queue');
      wire('wire-queue-worker', 'node-queue', 'node-worker');
      wire('wire-worker-db', 'node-worker', 'node-db');
    }
    if (stage >= 6) {
      // DNS 10.60 sits on its own ring between the clients and the network
      // hub; the cross-subnet Router is a side-card beside the 10.x hub on
      // the same ring, carrying the 10.65 ⇄ 20.1 interface pair.
      nodes['node-dns'] = pos('node-dns', 'ring-dns', ringRadius('ring-dns'), 170);
      nodes['node-router'] = pos('node-router', 'ring-network', networkRing.radius, 200);
      wire('wire-browser-dns', 'node-browser', 'node-dns');
      wire('wire-network-router', 'node-network', 'node-router');
    }
  }
  return {
    stage,
    rings,
    nodes,
    wires,
    satellites: browserSlots.map(({ index, x, y, angleDeg }) => ({ index, x, y, angleDeg })),
    browserSlots,
    bounds: {
      minX: -(outerRadius + 180),
      maxX: 120,
      // Stage 6's DNS/Router side-cards sit off the horizontal axis, so the
      // world frame grows taller to keep both cards inside pan and fit.
      minY: stage >= 6 ? -(gap + 500) : -(gap + 140),
      maxY: stage >= 6 ? gap + 500 : gap + 140,
    },
  };
}

