import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';

describe('createDns', () => {
  it('answers a cache hit inside ttlTicks with no authoritative consult', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    // Cold lookup: the authoritative table answers and fills the ledger.
    expect(dns.lookup('example.com', 0)).toEqual({ status: 'MISS', target: '10.1' });
    // Warm lookup one tick before expiry: the ledger answers, and the
    // lastLookup record proves no second authoritative consult happened.
    expect(dns.lookup('example.com', 299)).toEqual({ status: 'HIT', target: '10.1' });
    const snap = dns.snapshot(299);
    expect(snap.lookups).toBe(2);
    expect(snap.cachedHits).toBe(1);
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'HIT',
      target: '10.1',
      atTick: 299,
    });
    expect(snap.authoritative).toEqual({ 'example.com': '10.1' });
    expect(snap.cache).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 300, ttlRemaining: 1 },
    ]);
  });

  it('never answers an expired entry from the ledger', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    dns.lookup('example.com', 0);
    // At tick 300 the entry is exactly expired: the ledger must not answer,
    // so the lookup consults the authoritative table (a MISS, not a HIT)
    // and refills the entry with a fresh expiry.
    const expired = dns.lookup('example.com', 300);
    expect(expired).toEqual({ status: 'MISS', target: '10.1' });
    const snap = dns.snapshot(300);
    expect(snap.cachedHits).toBe(0);
    expect(snap.cache).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 600, ttlRemaining: 300 },
    ]);
  });

  it('answers NX for an unknown name without throwing and caches nothing', () => {
    const dns = createDns({ address: '10.60' });
    expect(dns.lookup('nope.example', 5)).toEqual({ status: 'NX' });
    const snap = dns.snapshot(5);
    expect(snap.lookups).toBe(1);
    expect(snap.cachedHits).toBe(0);
    expect(snap.cache).toEqual([]);
    expect(snap.lastLookup).toEqual({
      name: 'nope.example',
      status: 'NX',
      target: null,
      atTick: 5,
    });
  });

  it('rejects a non mini-IP address and a non positive integer ttlTicks', () => {
    expect(() => createDns({ address: '10.60.1' })).toThrow(/mini-IP address 10\.60\.1/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks must be a positive integer/);
    expect(() => createDns({ ttlTicks: 1.5 })).toThrow(/ttlTicks must be a positive integer/);
  });
});

import { describe, it, expect } from 'vitest';
import { createRouter } from '../../js/sim/router.js';
import { createNetwork } from '../../js/sim/network.js';
import { createWebServer } from '../../js/sim/webserver.js';

// A wired two-subnet fixture: 10.x runs a web server, 20.x holds only the
// router's own interface at 20.1 (the Stage 6a topology — nothing else
// lives there until Stage 6b's CDN edge).
function buildWired() {
  const left = createNetwork();
  const right = createNetwork();
  left.registerServer('10.1', createWebServer({ address: '10.1' }));
  const router = createRouter();
  router.join(left, right);
  left.attachRouter(router);
  right.attachRouter(router);
  right.registerServer('20.1', router);
  return { left, right, router };
}

describe('createRouter', () => {
  it('leaves same-subnet sends unchanged — the routed counter never moves', () => {
    const { left, router } = buildWired();
    expect(left.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      response: '200 This is the about page',
    });
    expect(router.snapshot().routed).toBe(0);
    expect(router.snapshot().lastRoute).toBe(null);
  });

  it('routes a cross-subnet frame in exactly one hop to the router 20-side', () => {
    const { left, router } = buildWired();
    expect(left.send({ from: '10.2', to: '20.1', request: 'GET /' })).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 Router interface 20.1',
    });
    expect(router.snapshot().routed).toBe(1);
    expect(router.snapshot().lastRoute).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      atTick: null,
    });
  });

  it('fails loud on an unregistered 20.x host (20.9), mirroring network.js', () => {
    const { left } = buildWired();
    expect(() => left.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    expect(() =>
      left.deliverToQueue({ id: '1:1', from: '10.2', to: '20.9', request: 'GET /', atTick: 1 }),
    ).toThrow(/no server at 20\.9/);
  });

  it('rides isYou through on a cross-subnet queue delivery', () => {
    const { left, right, router } = buildWired();
    // Register a plain queue target on the 20-side to observe the delivery.
    let enqueued = null;
    right.registerServer('20.5', {
      enqueue(record) {
        enqueued = record;
      },
      handleRequest() {
        return '200 20.5';
      },
    });
    left.deliverToQueue({
      id: 'you:4',
      from: '10.2',
      to: '20.5',
      request: 'GET /',
      atTick: 4,
      isYou: true,
    });
    expect(enqueued).toEqual({
      id: 'you:4',
      from: '10.2',
      to: '20.5',
      request: 'GET /',
      atTick: 4,
      isYou: true,
    });
    expect(router.snapshot().routed).toBe(1);
  });

  it('rejects invalid mini-IPs, a same-subnet interface pair, and a route before join', () => {
    expect(() => createRouter({ leftAddress: '10.650' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '2.1' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.9' })).toThrow(
      /must sit in different subnets/,
    );
    const detached = createRouter();
    expect(() => detached.route({ from: '10.2', to: '20.1', request: 'GET /' })).toThrow(
      /no networks joined/,
    );
    expect(() => detached.join(null, createNetwork())).toThrow(/join needs both/);
    // A frame addressed outside the two joined subnets has no route.
    const { left } = buildWired();
    expect(() => left.send({ from: '10.2', to: '30.1', request: 'GET /' })).toThrow(
      /no route to 30\.1/,
    );
  });
});

