input.newString:
// Stage 6 DNS hops: the ask runs the real resolver lookup — the tick-TTL
// cache ledger answers a warm name, the authoritative table a cold one,
// an unknown name is NX. The answer re-arms the GET with the resolved
// target and hands the trace to the chain (+2); NX answers, the browser
// renders the NX card, and NO GET is ever emitted.
function dnsHop(trace) {
  if (trace.hop === 1) {
    trace.hop = 2;
    const result = dns.lookup(trace.host, getTick());
    trace.dnsStatus = result.status;
    trace.dnsTarget = result.target ?? null;
    return `${trace.from} -> ${dns.address} | resolve ${trace.host}`;
  }
  trace.hop = 3;
  if (trace.dnsStatus === 'NX') {
    trace.nx = true;
    trace.totalHops = 3;
    trace.response = 'NX no record';
    trace.status = 'NX';
    trace.body = 'no record';
    onFinish({
      from: trace.from,
      to: dns.address,
      request: trace.request,
      response: 'NX no record',
    });
    return `${dns.address} -> ${trace.from} | NX no record (no GET emitted)`;
  }
  trace.request = `GET ${trace.pathOnly}`;
  trace.path = trace.pathOnly;
  return `${dns.address} -> ${trace.from} | ${trace.dnsTarget} (${trace.dnsStatus})`;
}

