        if (src[i] === '\\') i += 1;
        if (src[i] === '\n') line += 1;
        i += 1;
      }
      i += 1;
    } else if (ch === '/' && next === '/') {
      const startLine = line;
      const end = src.indexOf('\n', i);
      const raw = (end === -1 ? src.slice(i + 2) : src.slice(i + 2, end)).trim();
      blocks.push({ kind: 'line', line: startLine, text: raw });
      i = end === -1 ? src.length : end;
